SELECT CASE WHEN discount_pct >= 0.34 THEN 'HIGH' ELSE 'LOW' END AS discount_pct_tier, DATE_TRUNC('YEAR', starts_on) AS year_start, COUNT(*) FILTER (WHERE promo_code = 'VIP') AS vip_rows, STDDEV_SAMP(discount_pct) AS discount_pct_stddev, COUNT(*) AS event_count, SUM(CASE WHEN promo_code = 'SPRING10' THEN discount_pct ELSE 0 END) AS spring10_discount_pct FROM promotions GROUP BY CASE WHEN discount_pct >= 0.34 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('YEAR', starts_on) HAVING event_count < 1
